policy_require_flag('file_downloads');$id=(int)getv('id',0);$token=(string)getv('token','');
$s=db()->prepare('SELECT * FROM file_objects WHERE id=? AND public_token=? LIMIT 1');$s->execute([$id,$token]);$f=$s->fetch();if(!$f)exit('File not found.');if(!empty($f['trashed_at'])){http_response_code(410);exit('This file is in Trash and is not available.');}$shareToken=trim((string)getv('share',''));$share=null;if($shareToken!==''){ $sq=db()->prepare('SELECT s.* FROM file_share_links s JOIN file_share_items i ON i.share_id=s.id WHERE s.token=? AND i.file_id=?');$sq->execute([$shareToken,$id]);$share=$sq->fetch();if(!$share)exit('File is not part of this share.');if(!empty($share['revoked_at'])){http_response_code(410);exit('This share has been revoked.');}if(!empty($share['expires_at'])&&strtotime($share['expires_at'])<=time())exit('This share has expired.');if((int)$share['view_only']===1)exit('This share is view-only.');if((int)$share['max_downloads']>0&&(int)$share['downloads']>=(int)$share['max_downloads'])exit('Share download limit reached.');if(!empty($share['password_hash'])&&(int)($_SESSION['file_share_unlock_'.$share['id']]??0)<=time()-900)exit('This share requires its password.');}
if($f['status']!=='clean')exit('This file is not available yet.');if(!empty($f['password_hash']) && (int)($_SESSION['file_unlock_'.$f['id']]??0)<=time()-900)exit('This file requires the password from the share page.');
if(!empty($f['expires_at'])&&strtotime($f['expires_at'])<=time()){db()->prepare("UPDATE file_objects SET status='expired',updated_at=NOW() WHERE id=?")->execute([$id]);exit('This file has expired.');}
if((int)$f['max_downloads']>0&&(int)$f['downloads']>=(int)$f['max_downloads'])exit('Download limit reached.');if((int)($f['view_only']??0)===1)exit('This share is view-only. Downloads are disabled.');
