$path=file_local_path($f);if(!is_file($path)){http_response_code(404);header('Content-Type: text/plain; charset=utf-8');header('X-Content-Type-Options: nosniff');exit('File content not found.');}
if((int)getv('download',0)===1){$ticket=(string)getv('ticket','');$validTicket=false;$tk=$_SESSION['file_download_ticket_'.$id]??null;if(is_array($tk)&&hash_equals((string)($tk['token']??''),$ticket)&&time()<=(int)($tk['expires']??0)){$validTicket=true;unset($_SESSION['file_download_ticket_'.$id]);}if(!$validTicket){if((int)$f['max_downloads']>0){$u=db()->prepare('UPDATE file_objects SET downloads=downloads+1,updated_at=NOW() WHERE id=? AND downloads<max_downloads');$u->execute([$id]);if($u->rowCount()!==1)exit('Download limit reached.');}else db()->prepare('UPDATE file_objects SET downloads=downloads+1,updated_at=NOW() WHERE id=?')->execute([$id]);if($share){$u=db()->prepare('UPDATE file_share_links SET downloads=downloads+1,updated_at=NOW() WHERE id=? AND (max_downloads=0 OR downloads<max_downloads)');$u->execute([(int)$share['id']]);if($u->rowCount()!==1)exit('Share download limit reached.');}file_record_event($id,'download',(int)$f['size_bytes'],false);}}header('Content-Type: '.($f['mime_type']?:'application/octet-stream'));header('Content-Length: '.filesize($path));header('X-Content-Type-Options: nosniff');$name=basename(str_replace(["\r","\n"],'',(string)$f['original_name']));$fallback=preg_replace('/[^A-Za-z0-9._ -]/','_', $name)?:'download';$disposition=(int)getv('download',0)===1?'attachment':'inline';header('Content-Disposition: '.$disposition.'; filename="'.str_replace(['\\','"'],'_', $fallback).'"; filename*=UTF-8\'\''.rawurlencode($name));$fh=fopen($path,'rb');while(!feof($fh)){echo fread($fh,1048576);if(connection_aborted())break;}fclose($fh);exit;
